def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    # Count outcomes
    cc = cd = dc = dd = 0
    for (me, opp) in history:
        if me == 'C' and opp == 'C':
            cc += 1
        elif me == 'C' and opp == 'D':
            cd += 1
        elif me == 'D' and opp == 'C':
            dc += 1
        else:
            dd += 1

    total = n
    opp_c = cc + dc
    opp_d = cd + dd

    # Detect relentless defector quickly
    if opp_d == total and total >= 3:
        return 'D'

    # If opponent almost always cooperates, cooperate but occasionally exploit
    if opp_c >= total - 1 and total >= 10:
        # Exploit once in a while, otherwise cooperate
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    # Tit-for-tat with forgiveness and anti-noise
    last_me, last_opp = history[-1]

    # If opponent just defected, check if they've been generally cooperative
    if last_opp == 'D':
        # Forgive if opponent's cooperation rate is high
        if opp_c > opp_d:
            # Forgive occasionally
            if rng.random() < 0.3:
                return 'C'
        return 'D'

    # Opponent cooperated last
    # If we defected last and opponent still cooperates, they're very forgiving
    if last_me == 'D' and last_opp == 'C':
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    return 'C'

